// NewQueryRequestBody builds the HTTP request body from the payload of the
// "query" endpoint of the "analytics" service.
func NewQueryRequestBody(p *analytics.QueryPayload) *QueryRequestBody {
	body := &QueryRequestBody{
		Dataset:   p.Dataset,
		From:      p.From,
		To:        p.To,
		Grain:     p.Grain,
		Limit:     p.Limit,
		Ungrouped: p.Ungrouped,
	}
	if p.Dimensions != nil {
		body.Dimensions = make([]string, len(p.Dimensions))
		for i, val := range p.Dimensions {
			body.Dimensions[i] = val
		}
	}
	if p.Measures != nil {
		body.Measures = make([]*AnalyticsMeasureRequestBody, len(p.Measures))
		for i, val := range p.Measures {
			if val == nil {
				body.Measures[i] = nil
				continue
			}
			body.Measures[i] = marshalAnalyticsAnalyticsMeasureToAnalyticsMeasureRequestBody(val)
		}
	}
	if p.Filters != nil {
		body.Filters = make([]*AnalyticsFilterRequestBody, len(p.Filters))
		for i, val := range p.Filters {
			if val == nil {
				body.Filters[i] = nil
				continue
			}
			body.Filters[i] = marshalAnalyticsAnalyticsFilterToAnalyticsFilterRequestBody(val)
		}
	}
	if p.OrderBy != nil {
		body.OrderBy = make([]*AnalyticsOrderByRequestBody, len(p.OrderBy))
		for i, val := range p.OrderBy {
			if val == nil {
				body.OrderBy[i] = nil
				continue
			}
			body.OrderBy[i] = marshalAnalyticsAnalyticsOrderByToAnalyticsOrderByRequestBody(val)
		}
	}
	{
		var zero bool
		if body.Ungrouped == zero {
			body.Ungrouped = false
		}
	}
	return body
}

